import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

function validateRoot(root) {
  if (typeof root !== 'string' || !root) throw Error('root must be a non-symlink directory');
  // lstat("link/") follows the link on some platforms, so remove trailing separators.
  const normalized = path.normalize(root);
  const trimmed = normalized.length > 1 ? normalized.replace(/[\\/]+$/, '') : normalized;
  const stat = fs.lstatSync(trimmed || normalized);
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw Error('root must be a non-symlink directory');
}

function validatePath(selected) {
  if (typeof selected !== 'string' || !selected || selected.startsWith('/')
    || selected.includes('\\') || selected.includes('\0')
    || selected.split('/').some(part => !part || part === '.' || part === '..')) {
    throw Error('invalid selected path');
  }
}

function inspect(root, selected) {
  const parts = selected.split('/');
  let current = root;
  for (let i = 0; i < parts.length; i += 1) {
    current = path.join(current, parts[i]);
    let stat;
    try {
      stat = fs.lstatSync(current);
    } catch (error) {
      if (error.code === 'ENOENT') return { kind: 'missing' };
      throw error;
    }
    const final = i === parts.length - 1;
    if (stat.isSymbolicLink() || (final ? !stat.isFile() : !stat.isDirectory())) return { kind: 'unsafe' };
    if (final) {
      const bytes = fs.readFileSync(current);
      return {
        kind: 'file',
        sha256: crypto.createHash('sha256').update(bytes).digest('hex'),
        size: bytes.length,
        mode: stat.mode & 0o777,
      };
    }
  }
}

export function createManifest(root, paths) {
  validateRoot(root);
  if (!Array.isArray(paths)) throw Error('paths must be an array');
  const seen = new Set();
  for (const selected of paths) {
    validatePath(selected);
    if (seen.has(selected)) throw Error('duplicate selection');
    seen.add(selected);
  }
  return { version: 1, files: [...paths].sort().map(selected => {
    const current = inspect(root, selected);
    if (current.kind !== 'file') throw Error(`${current.kind} selected path`);
    return { path: selected, sha256: current.sha256, size: current.size, mode: current.mode };
  }) };
}

function validateManifest(manifest) {
  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)
    || manifest.version !== 1 || !Array.isArray(manifest.files)) {
    throw Error('invalid manifest');
  }
  const seen = new Set();
  for (const entry of manifest.files) {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) throw Error('invalid manifest entry');
    validatePath(entry.path);
    if (seen.has(entry.path)) throw Error('duplicate manifest path');
    seen.add(entry.path);
    if (typeof entry.sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(entry.sha256)
      || !Number.isSafeInteger(entry.size) || entry.size < 0
      || !Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777) {
      throw Error('invalid manifest entry');
    }
  }
}

export function verifyManifest(root, manifest) {
  // Validate every entry before touching the filesystem.
  validateManifest(manifest);
  validateRoot(root);
  const unchanged = [];
  const changed = [];
  const missing = [];
  const unsafe = [];
  for (const entry of manifest.files) {
    const current = inspect(root, entry.path);
    if (current.kind === 'missing') missing.push(entry.path);
    else if (current.kind === 'unsafe') unsafe.push(entry.path);
    else {
      const reasons = [];
      if (current.sha256 !== entry.sha256 || current.size !== entry.size) reasons.push('content');
      if (current.mode !== entry.mode) reasons.push('mode');
      if (reasons.length) changed.push({ path: entry.path, reasons });
      else unchanged.push(entry.path);
    }
  }
  const byPath = (a, b) => (typeof a === 'string' ? a : a.path) < (typeof b === 'string' ? b : b.path) ? -1 : (typeof a === 'string' ? a : a.path) > (typeof b === 'string' ? b : b.path) ? 1 : 0;
  unchanged.sort(byPath);
  changed.sort(byPath);
  missing.sort(byPath);
  unsafe.sort(byPath);
  return { ok: changed.length === 0 && missing.length === 0 && unsafe.length === 0, unchanged, changed, missing, unsafe };
}

function runCli(args) {
  const [command, root, ...rest] = args;
  if (command === 'create' && typeof root === 'string') {
    const manifest = createManifest(root, rest);
    process.stdout.write(`${JSON.stringify(manifest)}\n`);
    return 0;
  }
  if (command === 'verify' && typeof root === 'string' && rest.length === 1) {
    const manifest = JSON.parse(fs.readFileSync(rest[0], 'utf8'));
    const report = verifyManifest(root, manifest);
    process.stdout.write(`${JSON.stringify(report)}\n`);
    return report.ok ? 0 : 1;
  }
  throw Error('usage: snapshot.js create ROOT [PATH ...] | snapshot.js verify ROOT MANIFEST_FILE');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    process.exitCode = runCli(process.argv.slice(2));
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}
