import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { createManifest, verifyManifest } from '../snapshot.js';

const digest = value => crypto.createHash('sha256').update(value).digest('hex');
function temp(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-milestone-'));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  return root;
}
function run(...args) {
  return spawnSync(process.execPath, ['snapshot.js', ...args], { encoding: 'utf8' });
}
function assertCliError(result) {
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.notEqual(result.stderr, '');
}

test('verification accepts frozen unsorted manifests, ignores unknown fields, and handles empty manifests', t => {
  const root = temp(t);
  fs.writeFileSync(path.join(root, 'a'), 'a'); fs.chmodSync(path.join(root, 'a'), 0o640);
  fs.writeFileSync(path.join(root, 'z'), 'z'); fs.chmodSync(path.join(root, 'z'), 0o641);
  const made = createManifest(root, ['a', 'z']);
  const manifest = Object.freeze({ version: 1, ignored: true, files: Object.freeze([
    Object.freeze({ ...made.files[1], extra: 'ignored' }), Object.freeze({ ...made.files[0], extra: null }),
  ]) });
  assert.deepEqual(verifyManifest(root, manifest), { ok: true, unchanged: ['a', 'z'], changed: [], missing: [], unsafe: [] });
  assert.deepEqual(manifest.files.map(entry => entry.path), ['z', 'a']);
  assert.deepEqual(verifyManifest(root, { version: 1, files: [], ignored: {} }),
    { ok: true, unchanged: [], changed: [], missing: [], unsafe: [] });
});

test('manifest validation rejects all numeric and digest boundary defects', t => {
  const root = temp(t); fs.writeFileSync(path.join(root, 'x'), 'x');
  const good = { path: 'x', sha256: digest('x'), size: 1, mode: 0o644 };
  const badEntries = [
    { ...good, sha256: 'a'.repeat(63) }, { ...good, sha256: 'a'.repeat(65) },
    { ...good, sha256: 'a'.repeat(63) + '\n' }, { ...good, sha256: 'A'.repeat(64) },
    { ...good, size: -1 }, { ...good, size: 1.5 }, { ...good, size: Number.MAX_SAFE_INTEGER + 1 }, { ...good, size: '1' },
    { ...good, mode: -1 }, { ...good, mode: 512 }, { ...good, mode: 1.5 }, { ...good, mode: '1' },
  ];
  for (const entry of badEntries) assert.throws(() => verifyManifest(root, { version: 1, files: [entry] }), /invalid manifest entry/);
});

test('root checks preserve supplied pathname semantics and POSIX backslash names', t => {
  const root = temp(t); fs.writeFileSync(path.join(root, 'file'), 'x');
  assert.throws(() => createManifest(path.join(root, 'file', '..'), []));
  assert.throws(() => createManifest(path.join(root, 'missing', '..'), []));
  const link = `${root}-link`; fs.symlinkSync(root, link); t.after(() => fs.rmSync(link, { force: true }));
  assert.throws(() => createManifest(`${link}${path.sep}`, []));
  if (path.sep === '/') {
    const literal = `${root}\\`; fs.mkdirSync(literal); fs.writeFileSync(path.join(literal, 'x'), 'x'); fs.chmodSync(path.join(literal, 'x'), 0o640);
    assert.deepEqual(createManifest(literal, ['x']).files.map(entry => entry.path), ['x']);
  }
});

test('non-directory and symlink intermediate components are unsafe', t => {
  const root = temp(t);
  fs.writeFileSync(path.join(root, 'plain'), 'x'); fs.chmodSync(path.join(root, 'plain'), 0o640);
  fs.mkdirSync(path.join(root, 'target')); fs.writeFileSync(path.join(root, 'target', 'x'), 'x');
  fs.symlinkSync('target', path.join(root, 'linked'));
  const base = createManifest(root, ['plain']);
  const entry = base.files[0];
  assert.deepEqual(verifyManifest(root, { version: 1, files: [{ ...entry, path: 'plain/x' }, { ...entry, path: 'linked/x' }] }),
    { ok: false, unchanged: [], changed: [], missing: [], unsafe: ['linked/x', 'plain/x'] });
});

test('CLI create supports empty and unusual selections; error channels and import stay quiet', t => {
  const root = temp(t); const unusual = ' a\t\né';
  fs.writeFileSync(path.join(root, unusual), 'x'); fs.chmodSync(path.join(root, unusual), 0o640);
  let result = run('create', root);
  assert.equal(result.status, 0); assert.equal(result.stderr, ''); assert.equal(result.stdout, '{"version":1,"files":[]}\n');
  result = run('create', root, unusual);
  assert.equal(result.status, 0); assert.equal(result.stderr, ''); assert.deepEqual(JSON.parse(result.stdout), createManifest(root, [unusual]));
  const invalid = path.join(root, 'invalid.json'); fs.writeFileSync(invalid, '{');
  assertCliError(run('verify', root, invalid));
  const badManifest = path.join(root, 'bad.json'); fs.writeFileSync(badManifest, JSON.stringify({ version: 2, files: [] }));
  assertCliError(run('verify', root, badManifest));
  assertCliError(run('create')); assertCliError(run('verify', root)); assertCliError(run('verify', root, badManifest, 'extra'));
  assertCliError(run('create', path.join(root, 'no-root'))); assertCliError(run('create', root, '../bad'));
  result = spawnSync(process.execPath, ['-e', "import('./snapshot.js')"], { encoding: 'utf8' });
  assert.equal(result.status, 0); assert.equal(result.stdout, ''); assert.equal(result.stderr, '');
});

