import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { createManifest, verifyManifest } from '../snapshot.js';

function temp(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-contract-'));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  return root;
}
function hash(value) { return crypto.createHash('sha256').update(value).digest('hex'); }

test('manifest ordering, immutable inputs, empty selections, and valid unusual names', t => {
  const root = temp(t);
  fs.writeFileSync(path.join(root, 'z'), Buffer.from([0, 255, 10]));
  fs.writeFileSync(path.join(root, ' a\t\né'), 'x');
  fs.chmodSync(path.join(root, 'z'), 0o641);
  const paths = ['z', ' a\t\né'];
  const manifest = createManifest(root, paths);
  assert.deepEqual(paths, ['z', ' a\t\né']);
  assert.deepEqual(manifest.files.map(entry => entry.path), [' a\t\né', 'z']);
  assert.deepEqual(createManifest(root, []), { version: 1, files: [] });
  assert.deepEqual(manifest.files.find(entry => entry.path === 'z'), {
    path: 'z', sha256: hash(Buffer.from([0, 255, 10])), size: 3, mode: 0o641,
  });
});

test('verifier validates all fields before filesystem inspection and preserves unsorted manifest', () => {
  const bad = { version: 1, files: [
    { path: 'good', sha256: 'a'.repeat(64), size: 0, mode: 0 },
    { path: 'other', sha256: 'A'.repeat(64), size: 0, mode: 0 },
  ] };
  assert.throws(() => verifyManifest('/definitely-not-a-root', bad), /invalid manifest entry/);
  for (const manifest of [null, [], {}, { version: 2, files: [] }, { version: 1, files: {} },
    { version: 1, files: [null] }, { version: 1, files: [{ path: 'x', sha256: 'a'.repeat(64), size: -1, mode: 0 }] },
    { version: 1, files: [{ path: 'x', sha256: 'a'.repeat(64), size: 0, mode: 512 }] },
    { version: 1, files: [{ path: 'x', sha256: 'a'.repeat(64), size: 0, mode: 0 }, { path: 'x', sha256: 'a'.repeat(64), size: 0, mode: 0 }] },
  ]) assert.throws(() => verifyManifest('.', manifest));
  for (const badPath of ['', '/x', 'x\\y', 'x//y', './x', '../x', 'x/../y', 'x\0y']) {
    assert.throws(() => createManifest('.', [badPath]));
  }
});

test('verifier classifies all drift kinds and ignores unselected files', t => {
  const root = temp(t);
  for (const name of ['same', 'content', 'mode', 'both', 'gone', 'dir/file', 'link', 'finaldir']) {
    fs.mkdirSync(path.dirname(path.join(root, name)), { recursive: true });
    fs.writeFileSync(path.join(root, name), name);
  }
  const manifest = createManifest(root, ['both', 'content', 'dir/file', 'finaldir', 'gone', 'link', 'mode', 'same']);
  fs.writeFileSync(path.join(root, 'content'), 'changed');
  fs.chmodSync(path.join(root, 'mode'), 0o600);
  fs.writeFileSync(path.join(root, 'both'), 'changed'); fs.chmodSync(path.join(root, 'both'), 0o600);
  fs.unlinkSync(path.join(root, 'gone'));
  fs.unlinkSync(path.join(root, 'dir/file')); fs.rmdirSync(path.join(root, 'dir'));
  fs.unlinkSync(path.join(root, 'link')); fs.symlinkSync('same', path.join(root, 'link'));
  fs.unlinkSync(path.join(root, 'finaldir')); fs.mkdirSync(path.join(root, 'finaldir'));
  fs.writeFileSync(path.join(root, 'unselected'), 'irrelevant');
  assert.deepEqual(verifyManifest(root, manifest), {
    ok: false, unchanged: ['same'],
    changed: [{ path: 'both', reasons: ['content', 'mode'] }, { path: 'content', reasons: ['content'] }, { path: 'mode', reasons: ['mode'] }],
    missing: ['dir/file', 'gone'], unsafe: ['finaldir', 'link'],
  });
});

test('roots, symlink components, and CLI status streams obey contract', t => {
  const root = temp(t); fs.writeFileSync(path.join(root, 'a'), 'a');
  const linkedRoot = `${root}-link`; fs.symlinkSync(root, linkedRoot); t.after(() => fs.rmSync(linkedRoot, { force: true }));
  assert.throws(() => createManifest(linkedRoot + '/', ['a']));
  fs.symlinkSync('missing-target', path.join(root, 'dangling'));
  fs.symlinkSync('a', path.join(root, 'inside'));
  const manifest = createManifest(root, ['a']);
  assert.deepEqual(verifyManifest(root, { ...manifest, files: [{ ...manifest.files[0], path: 'dangling' }] }).unsafe, ['dangling']);
  assert.deepEqual(verifyManifest(root, { ...manifest, files: [{ ...manifest.files[0], path: 'inside' }] }).unsafe, ['inside']);
  const manifestFile = path.join(root, 'manifest.json'); fs.writeFileSync(manifestFile, JSON.stringify(manifest));
